SELECT d.id,v.id FROM source_documents d JOIN document_revisions v ON v.source_document_id=d.id AND v.is_current LEFT JOIN repository_locations l ON l.id=d.repository_location_id WHERE d.project_id=$1 AND d.path=$2 AND d.is_current AND d.freshness_status='current' AND ($3::text[] IS NULL OR EXISTS (SELECT 1 FROM unnest($3::text[]) AS allowed(root_path) WHERE l.root_path=allowed.root_path)) ORDER BY d.last_seen_at DESC LIMIT 1
